/* Writes src/runs.generated.ts from a fresh recording of the real code. Run: pnpm --filter @lab/race-figure generate */
import { writeFileSync } from 'node:fs'
import { recordRuns } from './record.ts'

const runs = await recordRuns()
const file = new URL('../src/runs.generated.ts', import.meta.url)
const body = `/*
 * Generated by scripts/generate.ts from the lab's real withdrawal code (build v0.1). Do not edit by hand.
 * ${runs.length} distinct runs of two withdrawals of 80 from a balance of 100. Format: see scripts/record.ts.
 */
export const RUNS: readonly string[] = [
${runs.map((run) => `  '${run}',`).join('\n')}
]
`
writeFileSync(file, body)
console.log(`Recorded ${runs.length} runs into src/runs.generated.ts`)
